<script setup lang="ts">
import {confirmAction,promptAction} from '../ui/confirm'
import { ref,computed,onMounted,onUnmounted } from 'vue'
import { onBeforeRouteLeave } from 'vue-router'
import { request } from '../api'
const settings=ref<any>(null),status=ref<any>({}),jobs=ref<any[]>([]),backups=ref<any[]>([]),busy=ref(false),error=ref(''),notice=ref(''),saved=ref('');let timer:ReturnType<typeof setInterval>|undefined,alive=true
const nextLocal=computed(()=>{if(!status.value.next_backup||!settings.value)return '';return new Intl.DateTimeFormat('zh-CN',{timeZone:settings.value.timezone,dateStyle:'full',timeStyle:'short'}).format(new Date(status.value.next_backup))})
const dirty=computed(()=>settings.value&&JSON.stringify(settings.value)!==saved.value)
async function leave(){return !busy.value&&(!dirty.value||await confirmAction('有未保存的维护设置，确定放弃吗？'))}
async function refresh(){const [s,j,b]=await Promise.all([request('/admin/maintenance/status'),request('/admin/maintenance/jobs'),request('/admin/maintenance/backups')]);if(alive){status.value=s;jobs.value=j;backups.value=b}}
async function load(){const s=await request('/admin/maintenance/settings');if(alive){settings.value=s;saved.value=JSON.stringify(s)}await refresh()}
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){if(alive)error.value=String(e)}finally{if(alive)busy.value=false}}
async function save(){const {revision,...value}=settings.value;settings.value=await request('/admin/maintenance/settings',{method:'PUT',body:JSON.stringify({...value,cleanup_reviewed:value.cleanup_confirmed,expected_revision:revision})});saved.value=JSON.stringify(settings.value);notice.value='维护设置已保存；下一次计划将在维护容器下次轮询更新';await refresh()}
async function queue(kind:string,id?:string){const confirmation=kind==='backup'?'执行备份':kind==='verify'?'验证备份':'永久清理';if(!await confirmAction(kind==='cleanup'?'按当前保留期限永久删除已过期文章及其专属数据？媒体原图保留。此操作不可通过回收站恢复。':kind==='backup'?'立即生成完整备份？一致性复制期间会暂时冻结保存，读取仍可使用。':'验证此备份的文件完整性？这不会自动恢复数据库。'))return;if(kind==='cleanup'&&await promptAction('请输入“永久清理”再次确认。')!=='永久清理')return;void run(async()=>{await request('/admin/maintenance/jobs',{method:'POST',body:JSON.stringify({kind,confirmation,expected_settings_revision:settings.value.revision,...(id?{artifact_id:id}:{})})});notice.value='任务已排队，请等待执行结果；排队不代表备份成功';await refresh()})}
function beforeUnload(e:BeforeUnloadEvent){if(dirty.value){e.preventDefault();e.returnValue=''}}
const stateLabel=(s:string)=>({queued:'等待执行',running:'执行中',succeeded:'执行完成',partial:'部分完成，请检查错误',failed:'失败'}[s]||s)
onBeforeRouteLeave(async()=>await leave());onMounted(()=>{window.addEventListener('beforeunload',beforeUnload);void run(load);timer=setInterval(()=>{if(!busy.value)void refresh().catch(e=>{if(alive)error.value=String(e)})},10000)});onUnmounted(()=>{alive=false;clearInterval(timer);window.removeEventListener('beforeunload',beforeUnload)})
</script>
<template><main class="container maintenance-admin"><h1>备份与恢复</h1><p>备份由独立维护容器执行。主 API 不挂载 SSD 备份目录 或 Docker Socket；网页不能提交宿主机路径或覆盖数据库。</p><p v-if="error" role="alert" class="error">{{error}}（设置输入保留）</p><p v-if="notice" role="status" class="notice">{{notice}}</p><p v-if="busy" role="status">正在处理…</p><section class="card"><h2>执行环境</h2><p v-if="!status.online" class="error">维护容器未运行或心跳过期。自动任务当前不可保证执行，请检查服务；不会假装备份成功。</p><p v-else-if="!status.configured" class="error">SSD 本地备份目录或应用版本未配置，或目录不可写。备份不可用；回收站定时清理仍由维护容器执行。</p><p v-else class="notice">维护容器在线，独立备份目录已配置。</p><p>数据库时钟（UTC）：{{status.now||'读取中'}}</p><p>下一次备份：{{nextLocal||'尚未安排或自动备份关闭'}}{{settings?' · 设置时区 '+settings.timezone:''}}</p><p v-if="status.retention_note">{{status.retention_note}}</p><p>最近成功：{{jobs.find(j=>j.kind==='backup'&&j.state==='succeeded')?.finished_at||backups.find(b=>b.verified_at)?.created_at||'尚无成功备份'}}</p><p>最近失败：{{jobs.find(j=>j.kind==='backup'&&j.state==='failed')?.error||'无已记录失败'}}</p></section><form v-if="settings" class="card" @submit.prevent="run(save)"><fieldset :disabled="busy"><h2>自动维护设置</h2><p v-if="!settings.cleanup_confirmed" class="notice">自动清理已暂停：首次启动或升级后，必须先审核历史回收记录及保留期，并明确确认保存。未确认时不会自动或手动批量清理。</p><label class="checks"><input v-model="settings.cleanup_confirmed" type="checkbox" aria-label="确认已审核清理策略"/>我已审核历史回收记录和保留期，授权按此策略永久清理（可取消以暂停）</label><label>回收站保留期限<select v-model="settings.retention_days" aria-label="回收站保留期限"><option :value="7">7 天</option><option :value="30">30 天（默认）</option><option :value="90">90 天</option><option value="never">永不自动清理</option></select></label><label class="checks"><input v-model="settings.backup_enabled" type="checkbox"/>启用自动备份</label><div class="editor-meta"><label>备份周期<select v-model="settings.frequency"><option value="daily">每天</option><option value="weekly">每周</option></select></label><label v-if="settings.frequency==='weekly'">每周执行日<select v-model.number="settings.weekday" aria-label="每周执行日"><option v-for="(name,i) in ['星期一','星期二','星期三','星期四','星期五','星期六','星期日']" :key="i" :value="i">{{name}}</option></select></label><label>执行时区<select v-model="settings.timezone" aria-label="执行时区"><option v-for="z in ['Asia/Shanghai','UTC','Asia/Tokyo','America/New_York','Europe/London']" :key="z">{{z}}</option></select></label><label>执行小时<input v-model.number="settings.hour" type="number" min="0" max="23" required/></label><label>执行分钟<input v-model.number="settings.minute" type="number" min="0" max="59" required/></label><label>保留完整备份数量<input v-model.number="settings.keep" type="number" min="1" max="52" required/></label></div><p>夏令时不存在的时刻跳过当次；重复时刻只运行第一次。首次实际恢复演练前不自动淘汰旧备份；演练后保留最近设置数量，并额外保护最后一次恢复验证副本。</p><div class="actions"><button>保存维护设置</button><button type="button" class="quiet" @click="async()=>{if(await leave())await run(load)}">取消维护修改</button><span v-if="dirty">有未保存修改</span></div></fieldset></form><section class="card"><h2>手动任务</h2><div class="actions"><button :disabled="busy||!status.configured||dirty" @click="queue('backup')">立即完整备份</button><button class="danger" :disabled="busy||!status.online||dirty||!settings?.cleanup_confirmed" @click="queue('cleanup')">按保留策略立即清理</button><button class="quiet" :disabled="busy" @click="run(refresh)">刷新任务状态</button></div></section><section class="card"><h2>完整备份</h2><p v-if="!backups.length">尚无成功且登记的完整备份。</p><article v-for="b in backups" :key="b.id" class="backup-row"><strong>{{b.created_at}}</strong><p>{{b.id}} · {{(b.size/1024/1024).toFixed(2)}} MB · {{b.file_count}} 个文件</p><p>应用 {{b.app_version}} · 迁移 {{b.schema_version}}</p><p>副本目录：{{b.present===true?'存在':b.present===false?'未找到':'待执行器检查'}} · 上次文件校验：{{b.verified_at?'已校验 '+b.verified_at:'未校验'}} · 实际恢复验证：{{b.restored_at||'未执行'}}（两者不同）</p><button :disabled="busy||!status.readable_backup||b.present===false" @click="queue('verify',b.id)">验证指定备份</button></article></section><section class="card"><h2>最近维护任务</h2><article v-for="j in jobs" :key="j.id" class="backup-row"><strong>{{j.kind==='backup'?'完整备份':j.kind==='verify'?'文件校验':'回收站清理'}} · {{stateLabel(j.state)}}</strong><p>{{j.created_at}} → {{j.finished_at||'尚未完成'}}</p><p v-if="j.error" class="error">{{j.error}}</p><p v-if="j.result.removed!==undefined">永久清理 {{j.result.removed}} 篇</p><p v-for="e in j.result.errors||[]" :key="e.id" class="error">{{e.id}} · {{e.reason}}</p><p v-if="j.result.retention?.note" class="notice">{{j.result.retention.note}}</p><p v-if="j.result.backup_id">备份编号 {{j.result.backup_id}} · 文件校验通过，实际恢复状态请看备份列表</p></article></section><details class="card"><summary>NVMe 故障后的恢复说明</summary><p>网页不提供覆盖恢复按钮。保管 SSD 完整备份及独立 HDD 副本、对应版本代码/镜像和独立环境配置；在全新 PostgreSQL 与空媒体目录使用兼容维护镜像主动执行恢复命令。先校验清单及应用/数据库版本，再实际恢复并启动应用验收。</p><p>完整步骤、恢复演练命令和密钥保管要求见仓库 docs/phase3h-recovery.md。恢复报告必须区分文件校验、数据库/媒体恢复与认证页面验收；只有最后一步完成才可登记实际恢复验证。</p></details></main></template>
<style scoped>.maintenance-admin>.card{margin:22px 0}.maintenance-admin .checks input{width:auto}.backup-row{padding:20px 0;border-bottom:1px solid var(--ui-line);overflow-wrap:anywhere}.maintenance-admin summary{min-height:44px;cursor:pointer}.maintenance-admin p{overflow-wrap:anywhere}.maintenance-admin fieldset{min-width:0}@media(max-width:600px){.maintenance-admin .editor-meta{grid-template-columns:1fr}.maintenance-admin .actions button{min-height:44px}}
</style>
